(() => {
  const STAMP='2026-09-17T17:00:00+02:00';
  const CUTOFF='2026-05-17';
  const CHECKED=new Set(['CAT','JBL','LMT','MCD','AMZN','MEDP','NTAP','RNG']);
  const CHANGED=new Set(['LMT']);
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const fmt=v=>new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)).replace(',',' ·');
  async function ready(){for(let i=0;i<60;i++){try{if(Array.isArray(holdings)&&holdings.length===12&&typeof renderCards==='function'&&typeof renderDetail==='function')return true}catch(_){}await sleep(100)}return false}
  function apply(){
    window.marketAgentUpdateMeta={contentUpdatedAt:STAMP,lastSuccessfulRunAt:STAMP,status:'partial',marketStatus:'US open'};
    holdings.forEach(h=>{if(!CHECKED.has(h.id))return;h.analysts=(h.analysts||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.insiders=(h.insiders||[]).filter(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date>=CUTOFF);h.lastCheckedAt=STAMP;h.changedSections=[];h.updateStatus='checked';delete h.updateTag});
    const lmt=holdings.find(h=>h.id==='LMT');if(lmt){
      lmt.triggers=lmt.triggers||[];
      if(!lmt.triggers.some(x=>x.date==='2026-09-17'&&/Morgan Stanley/.test(x.title||'')))lmt.triggers.unshift({date:'2026-09-17',title:'Morgan Stanley 14th Annual Laguna Conference',background:'CEO Jim Taiclet und CFO Evan Scott nehmen am 17.09. von 7:45 bis 8:20 Uhr PT an einem Fireside Chat teil. Zum Inhaltsstand 17:00 Europe/Berlin läuft das Zeitfenster noch; der IR-Webcast ist die Primärquelle.',direction:'neutral',criteria:[1,1,1],source:'https://investors.lockheedmartin.com/news-releases/news-release-details/lockheed-martin-ceo-and-cfo-speak-morgan-stanleys-14th-annual',sourceName:'Lockheed Martin IR',status:'laufend'});
      lmt.news=lmt.news||[];
      if(!lmt.news.some(x=>x.date==='2026-09-17'&&/AIM-260/.test(x.title||'')))lmt.news.unshift({date:'2026-09-17',sourceName:'Lockheed Martin',category:'Produktion / Auftragspfad',title:'Rahmenvereinbarung zur beschleunigten AIM-260-Produktion',summary:'Lockheed Martin und das US-Verteidigungsministerium vereinbarten einen Rahmen zur schnelleren Produktion und Lieferung des AIM-260 JATM. Die Vereinbarung soll die Basis für einen mehrjährigen Beschaffungsvertrag bilden, vorbehaltlich der Zustimmung des Kongresses.',impactText:'Positiv für langfristige Nachfrage- und Produktionsvisibilität; Stärke 2, da der konkrete Mehrjahresvertrag noch von der Zustimmung des Kongresses abhängt.',impact:2,source:'https://news.lockheedmartin.com/2026-09-17-Lockheed-Martin-and-Department-of-War-to-Accelerate-Air-Dominance-Missile-Production-Under-New-Agreement'});
      if(!lmt.news.some(x=>x.date==='2026-09-17'&&/GM Defense/.test(x.title||'')))lmt.news.unshift({date:'2026-09-17',sourceName:'Lockheed Martin',category:'Produktion / PAC-3',title:'GM Defense liefert erste PAC-3-MSE-Komponenten nach 22 Tagen',summary:'GM Defense lieferte erste PAC-3-MSE-Gehäusekomponenten weniger als einen Monat nach Vertragsabschluss. Lockheed wertet dies als Beleg für schnellere industrielle Skalierung; die Munitions- und Lagerflächen sollen nach geplanten Erweiterungen um fast 50 % wachsen.',impactText:'Positiv für Ausführung und Kapazitätsaufbau; Stärke 2, da noch kein separater Umsatz- oder Ergebnisbeitrag quantifiziert wurde.',impact:2,source:'https://news.lockheedmartin.com/2026-09-17-Lockheed-Martin-Fast-Tracks-PAC-3-R-MSE-Components-in-Less-Than-One-Month-in-Partnership-with-GM-Defense'});
      lmt.tailwinds=lmt.tailwinds||[];if(!lmt.tailwinds.some(x=>/AIM-260/.test(x)))lmt.tailwinds.unshift('Die neue AIM-260-JATM-Rahmenvereinbarung und die beschleunigte PAC-3-Zulieferung stützen die Visibilität für Munitionsproduktion und industrielle Skalierung; konkrete Mehrjahresvolumina bleiben teilweise noch offen.');
      lmt.lastChangedAt=STAMP;lmt.changedSections=['Termin/Trigger','News','Rückenwind/Risiken'];lmt.updateStatus='updated';lmt.updateTag='NEU';
    }
  }
  function badge(el,label){if(!el||el.querySelector('.update-badge'))return;const b=document.createElement('span');b.className='update-badge';b.textContent=label;el.prepend(b)}
  function mark(){const chip=document.getElementById('content-state-chip'),text=document.getElementById('content-state');if(chip&&text){text.textContent=`Inhalte: ${fmt(STAMP)}`;chip.classList.remove('status-ok','status-error','status-closed');chip.classList.add('status-partial');chip.title='US-Börsen regulär geöffnet. Acht US-Werte geprüft. Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet. 12er-Bestand gegen Dashboard und Marktdaten-Symbole abgeglichen; keine Position entfernt.'}document.querySelectorAll('.update-badge').forEach(e=>e.remove());document.querySelectorAll('.holding').forEach(c=>{c.classList.remove('content-changed','content-partial');const h=holdings.find(x=>x.id===c.dataset.id);if(CHANGED.has(c.dataset.id)){c.classList.add('content-changed');c.title=`Heute inhaltlich aktualisiert · ${(h?.changedSections||[]).join(', ')}`}else if(h&&CHECKED.has(h.id))c.title=`Letzte Inhaltsprüfung: ${fmt(STAMP)} · Keine inhaltliche Änderung`});if(selected==='LMT'){document.querySelectorAll('#tab-events .trigger').forEach(e=>{/Morgan Stanley 14th Annual Laguna/.test(e.textContent||'')&&badge(e.querySelector('.item-top'),'NEU')});document.querySelectorAll('#tab-events .news-item').forEach(e=>{if(/AIM-260|GM Defense/.test(e.textContent||''))badge(e.querySelector('.news-top'),'NEU')})}const footer=document.querySelector('footer.shell');if(footer)footer.textContent='Market Agent · Datenstand 17.09.2026 · 17:00 · Quellen in jedem Eintrag'}
  async function boot(){if(!(await ready()))return;apply();renderCards();renderDetail();mark();[500,1500,4000,8000].forEach(ms=>setTimeout(()=>{try{renderCards();renderDetail();mark()}catch(_){}},ms));document.addEventListener('click',e=>{if(e.target.closest('.holding,.tab,.filter'))setTimeout(mark,0)});window.addEventListener('pageshow',()=>setTimeout(mark,0))}boot();
})();